//! Runtime of the shared mock distribution.
//!
//! This is the normal-library half of the mock distribution; the proc-macro
//! half lives in `xbin-mock-distro`. It owns the process-global [`MockSystem`]
//! that stands in for a project's shared-memory pools and re-exports the
//! in-tree runtime items the generated code refers to, so a fixture
//! application only depends on this crate (the cross-binary pass injects the
//! synced `ipc_types` module into each `#[app]` module). The
//! `RticSwTask` trait the receivers implement is generated by the software
//! pass bound in `xbin-mock-distro` (M6.5-T5), not defined here.
//!
//! Because the system is process-global, applications expanded into one
//! process share the same pools while each gets the backend handle of its
//! own core through [`backend_for`].

use std::sync::LazyLock;

pub use rticx_xbin_mock::{MockBackend, MockSystem};
pub use rticx_xbin_rt as xbin_rt;

/// The fixtures' IPC pools, in process memory.
///
/// The pools are the three duals of the fixtures' fully connected `0<->1`,
/// `1<->2`, `0<->2` topology (M6.9-T6); both directions of a dual share the
/// pool's 4096-byte budget. `system.json` also gives each task its
/// pool-relative offset, so a fixture only ever looks up the pool of a dual it
/// declared; the extra pools are inert. The mock ignores the declared
/// addresses and sizes and uses the backing array's own.
pub fn system() -> &'static MockSystem {
    static SYSTEM: LazyLock<MockSystem> = LazyLock::new(|| {
        let mut system = MockSystem::new();
        system
            .add_pool(0, 1, 4096)
            .expect("the fixtures declare the `{0, 1}` pool");
        system
            .add_pool(1, 2, 4096)
            .expect("the three-application fixture declares the `{1, 2}` pool");
        system
            .add_pool(0, 2, 4096)
            .expect("the three-application fixture declares the `{0, 2}` pool");
        system
    });
    &SYSTEM
}

/// Returns the backend handle of global core `core`.
pub fn backend_for(core: u32) -> MockBackend {
    system().backend(core)
}
